    @Test public void copiedAndHexEditedBinaryBytesPersistThroughTheOriginalApprovedImmutablePackageAndColdOwnerReopen()throws Exception{
        tasks.authorizeTools(task,run,new JSONArray().put("project_inspect").put("project_read_file").put("project_search").put("project_plan").put("project_execute").put("project_package"));Files.write(files.resolve("asset-source.bin"),HEX_BEFORE);JSONObject copiedArgs=arguments(propose(new JSONArray().put(rawCopyEdit("assets/copied.bin"))));approve(copiedArgs);assertEquals("completed",dispatchApproved(copiedArgs).getString("status"));JSONObject hexArgs=arguments(propose(new JSONArray().put(hexEdit().put("path","assets/copied.bin"))));approve(hexArgs);assertEquals("completed",dispatchApproved(hexArgs).getString("status"));byte[] frozenBytes={0,(byte)255,0,3,4};assertArrayEquals(frozenBytes,Files.readAllBytes(files.resolve("assets/copied.bin")));
        JSONObject frozen=port.execute("project_plan",new JSONObject().put("intent","freeze_package").put("expectedSourceDigest",digest()).put("packageMode","source_project"),original);JSONObject freezeArgs=new JSONObject().put("planRef",frozen.getString("planRef")).put("planDigest",frozen.getString("planDigest")).put("stepId","freeze_package");approve(freezeArgs);JSONObject settled=dispatchApproved(freezeArgs);assertEquals(settled.toString(),"completed",settled.getString("status"));assertFalse(settled.getBoolean("businessVerified"));JSONObject packageResult=port.execute("project_package",new JSONObject().put("executionId",settled.getString("operationId")),original);String id=packageResult.getString("artifactId"),sha=packageResult.getString("archiveSha256");assertTrue(packageResult.getBoolean("immutable"));assertFalse(packageResult.getBoolean("authorityAdded"));assertFalse(packageResult.getBoolean("automaticallyExported"));
        Files.write(files.resolve("assets/copied.bin"),new byte[]{7,7});java.io.ByteArrayOutputStream archive=new java.io.ByteArrayOutputStream();local.exportProjectPackageForOwner(id,sha,archive);assertEquals(sha,ProjectSources.sha256(archive.toByteArray()));FeatureContext context=new FeatureContext(RuntimeEnvironment.getApplication(),null,null,event->{});try(LocalModule cold=new LocalModule(context,workspace,new NoProcess())){String selection=UUID.randomUUID().toString();JSONObject staged=cold.stageProjectPackageForOwner(new java.io.ByteArrayInputStream(archive.toByteArray()),selection),review=cold.planProjectPackageImportForOwner(selection,staged.getString("sha256"),"Explicit original binary package reopen",null),imported=cold.importProjectPackageForOwner(review.getJSONObject("plan"));String reopened=imported.getString("id");assertNotEquals(checkout,reopened);assertNotEquals(project,imported.getString("projectId"));assertFalse(imported.getBoolean("taskOrGrantRestored"));assertFalse(imported.getJSONObject("sourceImport").getBoolean("executionAuthorityRestored"));Path restored=files.getParent().getParent().resolve(reopened).resolve("files");assertArrayEquals(frozenBytes,Files.readAllBytes(restored.resolve("assets/copied.bin")));assertArrayEquals(HEX_BEFORE,Files.readAllBytes(restored.resolve("asset-source.bin")));assertArrayEquals(new byte[]{7,7},Files.readAllBytes(files.resolve("assets/copied.bin")));assertEquals(1,tasks.list().length());assertEquals(run,tasks.get(task,false).getString("runId"));assertEquals(checkout,tasks.get(task,false).getJSONObject("developmentContext").getString("checkoutId"));assertFalse(tasks.hasUnresolved(task));}
    }

    @Test public void originalReadPortAppliesExplicitExcludeBeforeItsOriginalBook9CaptureWithoutCreatingAnyWriteGrant()throws Exception{
        Files.createDirectories(files.resolve("logs"));writeUtf8(files.resolve("logs/private.txt"),"NEVER_CAPTURE_OWNED_EXCLUDED needle\n");writeUtf8(files.resolve("visible.txt"),"needle visible\n");JSONObject definition=null;JSONArray available=port.tools();for(int n=0;n<available.length();n++){JSONObject function=available.getJSONObject(n).getJSONObject("function");if("project_search".equals(function.optString("name")))definition=function;}assertNotNull(definition);assertTrue(definition.getJSONObject("parameters").getJSONObject("properties").has("exclude"));assertFalse(port.sideEffecting("project_search"));
        var binding=new ModelCapabilityAdapters.Binding(task,run,epoch,original,true,project);try(var captured=new ProjectCapabilityPort(binding,new TaskStoreCapabilityAuthority(tasks,binding,event->{}),original,null,local,tasks,checkout,"termux",tasks.toolOutputFactory(task,run,epoch,original,text->text))){JSONObject input=new JSONObject().put("mode","text").put("query","needle").put("exclude","logs/**");captured.validate("project_search",input);JSONObject result=captured.execute("project_search",input,original);assertEquals(1,result.getJSONArray("matches").length());assertEquals("visible.txt",result.getJSONArray("matches").getJSONObject(0).getString("path"));assertEquals(1,result.getInt("excludedByQuery"));assertFalse(result.toString().contains("NEVER_CAPTURE_OWNED_EXCLUDED"));JSONObject ref=result.getJSONObject("outputCapture").getJSONArray("outputRefs").getJSONObject(0);assertEquals(task,ref.getString("taskId"));assertEquals("project_search",ref.getString("tool"));assertEquals("",ref.getString("operationId"));var field=TaskStore.class.getDeclaredField("db");field.setAccessible(true);StringBuilder body=new StringBuilder();try(android.database.Cursor rows=((SQLiteDatabase)field.get(tasks)).rawQuery("SELECT body FROM task_output_chunks ORDER BY rowid",null)){while(rows.moveToNext())body.append(rows.getString(0));}assertTrue(body.toString().contains("needle visible"));assertFalse(body.toString().contains("NEVER_CAPTURE_OWNED_EXCLUDED"));assertEquals(0,tasks.get(task,false).getJSONArray("operations").length());assertEquals(1,tasks.list().length());assertEquals("NEVER_CAPTURE_OWNED_EXCLUDED needle\n",readUtf8(files.resolve("logs/private.txt")));}
    }

    private JSONObject moveEdit(String from,String to)throws Exception{return new JSONObject().put("action","move").put("fromPath",from).put("path",to).put("expectedHash","absent").put("expectedSourceHash",ProjectSources.sha256(HEX_BEFORE));}
    @Test public void aRealRenameUsesTheOriginalTwoPathApprovalReceiptAndNewApprovedConditionalRenameBack()throws Exception{
        Files.write(files.resolve("from.bin"),HEX_BEFORE);Files.createDirectory(files.resolve("dest"));JSONObject args=arguments(propose(new JSONArray().put(moveEdit("from.bin","dest/to.bin"))));approve(args);assertTrue(Files.exists(files.resolve("from.bin")));assertFalse(Files.exists(files.resolve("dest/to.bin")));JSONObject moved=dispatchApproved(args);assertEquals(moved.toString(),"completed",moved.getString("status"));assertFalse(Files.exists(files.resolve("from.bin")));assertArrayEquals(HEX_BEFORE,Files.readAllBytes(files.resolve("dest/to.bin")));assertEquals(2,moved.getInt("appliedFiles"));assertEquals("absent",moved.getJSONArray("files").getJSONObject(0).getString("actualAfterHash"));assertEquals(ProjectSources.sha256(HEX_BEFORE),moved.getJSONArray("files").getJSONObject(1).getString("actualAfterHash"));assertFalse(moved.getBoolean("crossFileAtomic"));JSONObject back=port.execute("project_plan",new JSONObject().put("intent","revert_operation").put("expectedSourceDigest",digest()).put("revertOperationId",moved.getString("operationId")),original);JSONObject reverseArgs=new JSONObject().put("planRef",back.getString("planRef")).put("planDigest",back.getString("planDigest")).put("stepId","revert_operation");approve(reverseArgs);assertEquals("completed",dispatchApproved(reverseArgs).getString("status"));assertArrayEquals(HEX_BEFORE,Files.readAllBytes(files.resolve("from.bin")));assertFalse(Files.exists(files.resolve("dest/to.bin")));assertEquals(1,tasks.list().length());assertFalse(tasks.hasUnresolved(task));
    }
